package net.civeira.phylax.features.access.dcrinitialaccesstoken.domain.valueobject;

import org.junit.jupiter.api.Assertions;
import org.junit.jupiter.api.DisplayName;
import org.junit.jupiter.api.Test;

import net.civeira.phylax.common.exception.ConstraintException;

class MaxUsesVOUnitTest {

  /**
   * @autogenerated ValueObjectGenerator
   */
  @Test
  @DisplayName("Test value object contruction for property max uses of dcr initial access token ")
  void test_max_uses_v_o_builder() {
    Assertions.assertThrows(ConstraintException.class, () -> MaxUsesVO.tryFrom(null));
    Assertions.assertEquals(1, MaxUsesVO.from(1).getMaxUses());
    Object falingInstance = new Object() {};
    Assertions.assertThrows(ConstraintException.class, () -> MaxUsesVO.tryFrom(falingInstance));
    Assertions.assertEquals("[" + 1 + "]", MaxUsesVO.from(1).toString());
  }
}
